int copy_auth_to_skb(struct xfrm_algo_auth *auth, struct sk_buff *skb) {
    struct nlattr *nla;
    size_t name_len = strlen(auth->alg_name) + 1;
    size_t key_len = auth->alg_key_len / 8;
    size_t total_len = sizeof(*nla) + name_len + key_len;

    nla = (struct nlattr *)__skb_put(skb, total_len);
    if (!nla) {
        return -EMSGSIZE;
    }

    nla->nla_type = XFRMA_ALG_AUTH;
    nla->nla_len = total_len;

    char *data = (char *)nla + sizeof(*nla);

    if (name_len > 0) {
        strncpy(data, auth->alg_name, name_len);
        data += name_len;
    }

    if (key_len > 0) {
        memcpy(data, auth->alg_key, key_len);
    }

    return 0;
}
